#!/usr/bin/env bash
# Generates config.js from .env (the browser can't read .env directly).
set -euo pipefail
cd "$(dirname "$0")"
[ -f .env ] || { echo "No .env found — copy .env.example to .env first." >&2; exit 1; }
set -a; . ./.env; set +a
cat > config.js <<JS
// Generated by build-config.sh from .env — do not edit or commit.
window.BSIDE_CONFIG = {
  googleClientId: '${GOOGLE_CLIENT_ID:-}'
};
JS
echo "Wrote config.js"
